<script>document.addEventListener('DOMContentLoaded',function(){document.querySelectorAll('[data-expert-slider]').forEach(function(slider){const track=slider.querySelector('.dsp2-track'),cards=[...track.children],prev=slider.querySelector('.dsp2-prev'),next=slider.querySelector('.dsp2-next');let index=0;function visible(){return window.innerWidth<=700?1:(window.innerWidth<=1100?3:5)}function update(){const show=visible(),max=Math.max(0,cards.length-show),step=(cards[0]?.getBoundingClientRect().width||0)+16;index=Math.min(index,max);track.style.transform=`translateX(-${index*step}px)`;slider.classList.toggle('is-scrollable',cards.length>show);prev.disabled=index===0;next.disabled=index>=max}prev.addEventListener('click',()=>{index=Math.max(0,index-1);update()});next.addEventListener('click',()=>{index=Math.min(Math.max(0,cards.length-visible()),index+1);update()});window.addEventListener('resize',update);update()})});document.querySelectorAll('[data-review-slider]').forEach(function(slider){const track=slider.querySelector('.dsp2-review-track'),cards=[...track.children],dots=slider.parentElement.querySelector('.dsp2-review-dots');let active=Math.min(1,cards.length-1);cards.forEach((card,i)=>{const dot=document.createElement('button');dot.type='button';dot.setAttribute('aria-label','Show review '+(i+1));dot.onclick=()=>{active=i;update()};dots.appendChild(dot)});function update(){cards.forEach((card,i)=>card.classList.toggle('is-active',i===active));[...dots.children].forEach((dot,i)=>dot.classList.toggle('is-active',i===active));if(window.innerWidth<=700){const step=(cards[0]?.getBoundingClientRect().width||0)+12;track.style.transform=`translateX(-${active*step}px)`}else if(cards.length>3){const offset=Math.max(0,Math.min(active-1,cards.length-3)),step=(cards[0]?.getBoundingClientRect().width||0)+20;track.style.transform=`translateX(-${offset*step}px)`}else track.style.transform='translateX(0)'}window.addEventListener('resize',update);update()})});</script>
